{"command": "A='Jonathan Ong\|jongleberry'
echo all-nomerge-total $(git log --no-merges --format=%h|wc -l)
echo author-nomerge $(git log --no-merges --format=%h -i --author="$A"|wc -l)
echo in-window total $(git log --no-merges --format=%h --since=2013-11-07 --until=2015-08-22|wc -l)
echo in-window author $(git log --no-merges --format=%h -i --author="$A" --since=2013-11-07 --until=2015-08-22|wc -l)
git log --no-merges --format='%aE|%aN' | grep -i -E 'jong|ong' | sort | uniq -c
echo authors $(git log --no-merges --format=%aE|sort -u|wc -l)
echo files; git ls-tree -r --name-only HEAD | wc -l
git blame --line-porcelain -w -M HEAD -- $(git ls-files) 2>/dev/null | awk '/^author /{a=substr($0,8)} /^\t/{c[a]++;t++} END{for(k in c)print c[k],k; print t,"TOTAL"}' | sort -rn | head -6
git tag | wc -l; git status --short"}
